\begin{scope}[rotate=45]
\draw (0,0) ellipse [x radius=2.2,y radius=1.3];
\pgfmathsetmacro{\xa}{1.1*sqrt(3)}
\pgfmathsetmacro{\yb}{0.65*sqrt(3)}
\coordinate (A1) at (-\xa,0.65);
